input.newString:
  cancel(id: number): Order {
    const order = this.get(id);
    if (order.status !== "PENDING") throw conflict("ORDER_NOT_PENDING", `order ${id} is ${order.status}`);
    this.orders.updateStatus(id, "CANCELLED");
    return this.get(id);
  }

  applyCoupon(id: number, couponCode: unknown): Order {
    const order = this.get(id);
    if (typeof couponCode !== "string" || couponCode.trim() === "") {
      throw badRequest("INVALID_REQUEST", "couponCode is required");
    }
    const code = couponCode.trim();
    const coupon = this.coupons.findByCode(code);
    if (!coupon) throw badRequest("COUPON_NOT_FOUND", `coupon ${code} not found`);
    if (coupon.status !== "ACTIVE") throw badRequest("COUPON_NOT_ACTIVE", `coupon ${code} is not active`);

    const now = this.clock().getTime();
    if (now < Date.parse(coupon.validFrom) || now > Date.parse(coupon.validUntil)) {
      throw badRequest("COUPON_EXPIRED", `coupon ${code} is not valid at this time`);
    }
    if (order.amountCents < coupon.minAmountCents) {
      throw badRequest(
        "COUPON_MIN_AMOUNT",
        `order amount ${order.amountCents} is below coupon minimum ${coupon.minAmountCents}`,
      );
    }
    if (coupon.usageLimit !== null && coupon.usedCount >= coupon.usageLimit) {
      throw badRequest("COUPON_USAGE_LIMIT", `coupon ${code} has reached its usage limit`);
    }

    let discount =
      coupon.type === "FIXED" ? coupon.value : Math.floor((order.amountCents * coupon.value) / 100);
    if (coupon.maxDiscountCents !== null) discount = Math.min(discount, coupon.maxDiscountCents);
    discount = Math.min(discount, order.amountCents);

    this.orders.applyCoupon(order.id, coupon.code, discount);
    this.coupons.recordRedemption(order.id, coupon.code, discount, this.clock().toISOString());
    return this.get(order.id);
  }
}

